<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';require __DIR__.'/ticket_service.php';
saas_require_login();$tourId=saas_require_tour();saas_require_permission('payment.create');$db=saas_db();$error='';$ok='';$editPaymentId=(int)($_GET['edit']??0);$selectedPassengerId=(int)($_GET['passenger_id']??$_POST['tour_passenger_id']??0);$orgId=(int)saas_current_organization()['id'];
if($_SERVER['REQUEST_METHOD']==='POST'){saas_check_csrf();try{$action=(string)($_POST['action']??'');if($action==='update_payment'){saas_require_permission('payment.create');$id=(int)($_POST['payment_id']??0);$amount=round((float)($_POST['amount']??0),2);$method=strtoupper(trim((string)($_POST['method']??'CASH')));$ref=trim((string)($_POST['reference']??''));$date=trim((string)($_POST['payment_date']??date('Y-m-d')));$notes=trim((string)($_POST['notes']??''));$allowed=['CASH','BKASH','NAGAD','ROCKET','BANK','CARD','ONLINE','OTHER'];if($id<=0||$amount<=0)throw new RuntimeException('Payment and a positive amount are required.');if(!in_array($method,$allowed,true))throw new RuntimeException('Invalid payment method.');if(!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$date))throw new RuntimeException('Invalid payment date.');$q=$db->prepare('SELECT p.id,p.tour_passenger_id,p.amount,tp.fee,tp.discount FROM payments p JOIN tour_passengers tp ON tp.id=p.tour_passenger_id JOIN tours t ON t.id=p.tour_id WHERE p.id=? AND p.tour_id=? AND t.organization_id=? LIMIT 1');$q->execute([$id,$tourId,$orgId]);$old=$q->fetch();if(!$old)throw new RuntimeException('Payment not found.');$q=$db->prepare("SELECT COALESCE(SUM(total_price),0) FROM tour_passenger_features WHERE tour_id=? AND tour_passenger_id=? AND status='SELECTED'");$q->execute([$tourId,(int)$old['tour_passenger_id']]);$featureTotal=(float)$q->fetchColumn();$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=? AND id<>?');$q->execute([(int)$old['tour_passenger_id'],$tourId,$id]);$otherPaid=(float)$q->fetchColumn();$gross=round(max(0,(float)$old['fee']-(float)$old['discount'])+$featureTotal,2);if($amount>$gross-$otherPaid+0.005)throw new RuntimeException('Payment exceeds the passenger\'s remaining due amount of '.number_format(max(0,$gross-$otherPaid),2).'.');$q=$db->prepare('UPDATE payments SET amount=?,payment_method=?,transaction_reference=?,payment_date=?,notes=? WHERE id=? AND tour_id=?');$q->execute([$amount,$method,$ref?:null,$date,$notes?:null,$id,$tourId]);$editPaymentId=0;$ok='Payment updated successfully.';}elseif($action==='add_payment'){$tpId=(int)($_POST['tour_passenger_id']??0);$selectedPassengerId=$tpId;$amount=round((float)($_POST['amount']??0),2);$method=strtoupper(trim((string)($_POST['method']??'CASH')));$ref=trim((string)($_POST['reference']??''));$date=trim((string)($_POST['payment_date']??date('Y-m-d')));$notes=trim((string)($_POST['notes']??''));if(!$tpId||$amount<=0)throw new RuntimeException('Passenger and a positive payment amount are required.');$allowed=['CASH','BKASH','NAGAD','ROCKET','BANK','CARD','ONLINE','OTHER'];if(!in_array($method,$allowed,true))throw new RuntimeException('Invalid payment method.');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date))throw new RuntimeException('Invalid payment date.');$db->beginTransaction();$q=$db->prepare("SELECT tp.id,tp.status,tp.fee,tp.discount,pp.full_name FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=tp.tour_id WHERE tp.id=? AND tp.tour_id=? AND t.organization_id=? AND tp.status<>'CANCELLED' FOR UPDATE");$q->execute([$tpId,$tourId,$orgId]);$p=$q->fetch();if(!$p)throw new RuntimeException('Passenger does not belong to this tour.');$q=$db->prepare("SELECT COALESCE(SUM(total_price),0) FROM tour_passenger_features WHERE tour_id=? AND tour_passenger_id=? AND status='SELECTED'");$q->execute([$tourId,$tpId]);$featureTotal=(float)$q->fetchColumn();$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?');$q->execute([$tpId,$tourId]);$paid=(float)$q->fetchColumn();$gross=round(max(0,(float)$p['fee']-(float)$p['discount'])+$featureTotal,2);$due=max(0,$gross-$paid);if($amount>$due+0.005)throw new RuntimeException('Payment exceeds the current due amount of '.number_format($due,2).'.');$paymentReference='PAY-'.date('YmdHis').'-'.strtoupper(bin2hex(random_bytes(4)));$q=$db->prepare('INSERT INTO payments(organization_id,tour_id,tour_passenger_id,payment_reference,amount,payment_method,transaction_reference,payment_date,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$q->execute([$orgId,$tourId,$tpId,$paymentReference,$amount,$method,$ref?:null,$date,$notes?:null,saas_user_id()]);$id=(int)$db->lastInsertId();$newDue=max(0,$gross-($paid+$amount));$ticket=null;if($newDue<=0.005)$ticket=saas_issue_ticket($db,$tourId,$tpId,$orgId);$db->commit();saas_audit('payment.created','payment',$id,json_encode(['tour_passenger_id'=>$tpId,'amount'=>$amount,'method'=>$method],JSON_UNESCAPED_UNICODE));if($ticket)saas_audit('ticket.auto_issued','ticket_instance',(int)$ticket['id'],json_encode(['tour_passenger_id'=>$tpId,'payment_id'=>$id],JSON_UNESCAPED_UNICODE));$ok=$ticket?'Payment recorded and ticket automatically issued for '.$p['full_name'].'.':'Payment recorded for '.$p['full_name'].'.';}
elseif($action==='delete_payment'){saas_require_permission('payment.delete');$id=(int)($_POST['payment_id']??0);$db->beginTransaction();$q=$db->prepare("SELECT p.id,p.amount,p.tour_passenger_id,tp.fee,tp.discount FROM payments p JOIN tour_passengers tp ON tp.id=p.tour_passenger_id JOIN tours t ON t.id=p.tour_id WHERE p.id=? AND p.tour_id=? AND t.organization_id=? FOR UPDATE");$q->execute([$id,$tourId,$orgId]);$pay=$q->fetch();if(!$pay)throw new RuntimeException('Payment not found.');$q=$db->prepare('DELETE FROM payments WHERE id=? AND tour_id=?');$q->execute([$id,$tourId]);$q=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM payments WHERE tour_passenger_id=? AND tour_id=?');$q->execute([(int)$pay['tour_passenger_id'],$tourId]);$remainingPaid=(float)$q->fetchColumn();$q=$db->prepare("SELECT COALESCE(SUM(total_price),0) FROM tour_passenger_features WHERE tour_id=? AND tour_passenger_id=? AND status='SELECTED'");$q->execute([$tourId,(int)$pay['tour_passenger_id']]);$featureTotal=(float)$q->fetchColumn();$newDue=max(0,round((float)$pay['fee']-(float)$pay['discount']+$featureTotal-$remainingPaid,2));$voidedTicketId=0;if($newDue>0.005){$q=$db->prepare("SELECT id FROM ticket_instances WHERE tour_passenger_id=? AND tour_id=? AND status='ISSUED' AND voided_at IS NULL ORDER BY id DESC LIMIT 1 FOR UPDATE");$q->execute([(int)$pay['tour_passenger_id'],$tourId]);$activeTicket=$q->fetch();if($activeTicket){$voidedTicketId=(int)$activeTicket['id'];$q=$db->prepare("UPDATE ticket_instances SET qr_token_revoked_at=NOW(),status='VOID',voided_at=NOW(),updated_at=NOW() WHERE id=?");$q->execute([$voidedTicketId]);}}$db->commit();saas_audit('payment.deleted','payment',$id,json_encode(['amount'=>$pay['amount'],'tour_passenger_id'=>$pay['tour_passenger_id']]));if($voidedTicketId)saas_audit('ticket.auto_voided','ticket_instance',$voidedTicketId,json_encode(['reason'=>'payment_deleted','payment_id'=>$id],JSON_UNESCAPED_UNICODE));$ok=$voidedTicketId?'Payment deleted and ticket voided because a balance remains.':'Payment deleted.';}}
catch(Throwable $e){if($db->inTransaction())$db->rollBack();$error=$e->getMessage();}}
$q=$db->prepare("SELECT tp.id,pp.full_name,pp.phone,tp.fee,tp.discount,COALESCE(SUM(p.amount),0) paid,COALESCE((SELECT SUM(tpf.total_price) FROM tour_passenger_features tpf WHERE tpf.tour_id=tp.tour_id AND tpf.tour_passenger_id=tp.id AND tpf.status='SELECTED'),0) feature_total FROM tour_passengers tp JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id LEFT JOIN payments p ON p.tour_passenger_id=tp.id AND p.tour_id=tp.tour_id WHERE tp.tour_id=? AND tp.status<>'CANCELLED' GROUP BY tp.id,pp.full_name,pp.phone,tp.fee,tp.discount ORDER BY pp.full_name");$q->execute([$tourId]);$passengers=$q->fetchAll();$q=$db->prepare("SELECT p.*,pp.full_name FROM payments p JOIN tour_passengers tp ON tp.id=p.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=p.tour_id WHERE p.tour_id=? AND t.organization_id=? ORDER BY p.payment_date DESC,p.id DESC");$q->execute([$tourId,$orgId]);$payments=$q->fetchAll();$editPayment=null;if($editPaymentId){$q=$db->prepare('SELECT p.*,pp.full_name FROM payments p JOIN tour_passengers tp ON tp.id=p.tour_passenger_id JOIN passenger_profiles pp ON pp.id=tp.passenger_profile_id JOIN tours t ON t.id=p.tour_id WHERE p.id=? AND p.tour_id=? AND t.organization_id=? LIMIT 1');$q->execute([$editPaymentId,$tourId,$orgId]);$editPayment=$q->fetch()?:null;} $totalDue=0;$totalPaid=0;foreach($passengers as $p){$totalPaid+=(float)$p['paid'];$totalDue+=max(0,(float)$p['fee']-(float)$p['discount']+(float)$p['feature_total']-(float)$p['paid']);}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Payments</title><style>*{box-sizing:border-box}body{font-family:Inter,Arial,sans-serif;background:#f4f7fb;margin:0;color:#172033}.wrap{max-width:1200px;margin:25px auto;padding:0 16px}.box{background:#fff;border-radius:16px;padding:20px;margin-bottom:18px;box-shadow:0 6px 22px #0000000b}.grid{display:grid;grid-template-columns:minmax(0,350px) minmax(0,1fr);gap:18px}.grid>.box{min-width:0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{display:block;font-size:13px;font-weight:700;margin:10px 0 5px}input,select,textarea,button{width:100%;padding:10px;border:1px solid #d0d5dd;border-radius:9px;font:inherit}textarea{min-height:65px;resize:vertical}button{margin-top:12px;background:#155eef;color:#fff;border-color:#155eef;cursor:pointer;font-weight:700}.msg{padding:11px;border-radius:9px;margin-bottom:15px}.ok{background:#ecfdf3;color:#067647}.err{background:#fef3f2;color:#b42318}.stats{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.stat{border:1px solid #eaecf0;border-radius:12px;padding:14px}.stat b{display:block;font-size:22px;margin-top:5px}.muted{color:#667085;font-size:13px}table{width:100%;border-collapse:collapse;min-width:760px}th,td{padding:10px;border-bottom:1px solid #eee;text-align:left;white-space:nowrap}.tablewrap{width:100%;max-width:100%;overflow-x:auto;overflow-y:hidden;-webkit-overflow-scrolling:touch}.due{font-weight:700}.paid{color:#067647}.smallbtn{padding:6px 9px;margin:0;background:#fff;color:#b42318;border-color:#fecdca;font-size:12px}.payment-actions{display:flex;align-items:center;justify-content:flex-end;gap:6px;white-space:nowrap}.edit-payment,.cancel-edit{display:inline-flex;align-items:center;justify-content:center;padding:6px 9px;border:1px solid #b2ddff;border-radius:8px;background:#eff8ff;color:#175cd3;text-decoration:none;font-size:12px;font-weight:800}.cancel-edit{margin-left:8px;background:#fff;color:#475467;border-color:#d0d5dd}.history{margin-top:18px}.focus{border:1px solid #b2ddff;background:#eff8ff;padding:10px;border-radius:9px;margin-bottom:10px;font-size:13px}@media(max-width:850px){.grid{grid-template-columns:minmax(0,1fr)}.grid>.box{min-width:0}.fields{grid-template-columns:1fr}.stats{grid-template-columns:1fr}}
</style></head><body><main class="wrap"><p><a href="registrations.php">← Registrations</a> · <a href="dashboard.php">Dashboard</a></p><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><h1>Payments</h1><div style="display:flex;gap:7px"><a class="btn" target="_blank" href="export.php?type=payments&format=pdf">Print / PDF</a><a class="btn" href="export.php?type=payments&format=excel">Excel</a></div></div><?php if($ok):?><div class="msg ok"><?=saas_h($ok)?></div><?php endif;?><?php if($error):?><div class="msg err"><?=saas_h($error)?></div><?php endif;?><?php if($selectedPassengerId):?><div class="focus">Payment workflow opened for the selected passenger. Choose the passenger below and record the received amount.</div><?php endif;?><section class="box stats"><div class="stat"><span class="muted">Total received</span><b><?=number_format($totalPaid,2)?></b></div><div class="stat"><span class="muted">Total outstanding</span><b><?=number_format($totalDue,2)?></b></div></section><div class="grid"><section class="box"><h2><?= $editPayment?'Edit payment':'Record payment' ?></h2><form method="post"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><?php if($editPayment):?><input type="hidden" name="action" value="update_payment"><input type="hidden" name="payment_id" value="<?=$editPayment['id']?>"><?php else:?><input type="hidden" name="action" value="add_payment"><?php endif;?><label>Passenger</label><select name="tour_passenger_id" required <?= $editPayment?'disabled':'' ?>><option value="">Select passenger</option><?php foreach($passengers as $p):$due=max(0,(float)$p['fee']-(float)$p['discount']+(float)$p['feature_total']-(float)$p['paid']);?><option value="<?=$p['id']?>" <?=($selectedPassengerId===(int)$p['id']?'selected ':'')?><?=($due<=0?'disabled':'')?>><?=saas_h($p['full_name'])?> — Due <?=number_format($due,2)?></option><?php endforeach;?></select><div class="fields"><div><label>Amount</label><input type="number" name="amount" min="0.01" step="0.01" required value="<?= $editPayment?saas_h((string)$editPayment['amount']):'' ?>"></div><div><label>Date</label><input type="date" name="payment_date" value="<?= $editPayment?saas_h((string)$editPayment['payment_date']):date('Y-m-d') ?>" required></div></div><div class="fields"><div><label>Method</label><select name="method"><option <?=($editPayment&&$editPayment['payment_method']==='CASH')?'selected':''?>>CASH</option><option <?=($editPayment&&$editPayment['payment_method']==='BKASH')?'selected':''?>>BKASH</option><option <?=($editPayment&&$editPayment['payment_method']==='NAGAD')?'selected':''?>>NAGAD</option><option <?=($editPayment&&$editPayment['payment_method']==='ROCKET')?'selected':''?>>ROCKET</option><option <?=($editPayment&&$editPayment['payment_method']==='BANK')?'selected':''?>>BANK</option><option <?=($editPayment&&$editPayment['payment_method']==='CARD')?'selected':''?>>CARD</option><option <?=($editPayment&&$editPayment['payment_method']==='ONLINE')?'selected':''?>>ONLINE</option><option <?=($editPayment&&$editPayment['payment_method']==='OTHER')?'selected':''?>>OTHER</option></select></div><div><label>Reference</label><input name="reference" value="<?= $editPayment?saas_h((string)($editPayment['transaction_reference']??'')):'' ?>" placeholder="Txn / receipt no."></div></div><label>Notes</label><textarea name="notes"><?= $editPayment?saas_h((string)($editPayment['notes']??'')):'' ?></textarea><button><?= $editPayment?'Update payment':'Save payment' ?></button><?php if($editPayment):?><a class="cancel-edit" href="payments.php">Cancel</a><?php endif;?></form></section><section class="box"><h2>Passenger balances</h2><div class="tablewrap"><table><tr><th>Passenger</th><th>Base Fee</th><th>Options</th><th>Discount</th><th>Paid</th><th>Due</th></tr><?php foreach($passengers as $p):$due=max(0,(float)$p['fee']-(float)$p['discount']+(float)$p['feature_total']-(float)$p['paid']);?><tr><td><?=saas_h($p['full_name'])?><div class="muted"><?=saas_h($p['phone']??'')?></div></td><td><?=number_format((float)$p['fee'],2)?></td><td><?=number_format((float)$p['feature_total'],2)?></td><td><?=number_format((float)$p['discount'],2)?></td><td class="paid"><?=number_format((float)$p['paid'],2)?></td><td class="due"><?=number_format($due,2)?></td></tr><?php endforeach;?></table></div></section></div><section class="box history"><h2>Payment history</h2><div class="tablewrap"><table><tr><th>Date</th><th>Passenger</th><th>Amount</th><th>Method</th><th>Reference</th><th></th></tr><?php foreach($payments as $p):?><tr><td><?=saas_h($p['payment_date'])?></td><td><?=saas_h($p['full_name'])?></td><td><?=number_format((float)$p['amount'],2)?></td><td><?=saas_h($p['payment_method']??'')?></td><td><?=saas_h($p['transaction_reference']??$p['payment_reference']??'')?></td><td><div class="payment-actions"><a class="edit-payment" href="payments.php?edit=<?=$p['id']?>">Edit</a><?php if(saas_can('payment.delete')):?><form method="post" onsubmit="return confirm('Delete this payment?')"><input type="hidden" name="csrf" value="<?=saas_h(saas_csrf())?>"><input type="hidden" name="action" value="delete_payment"><input type="hidden" name="payment_id" value="<?=$p['id']?>"><button class="smallbtn">Delete</button></form><?php endif;?></div></td></tr><?php endforeach;?></table><?php if(!$payments):?><p class="muted">No payments recorded yet.</p><?php endif;?></div></section></main></body></html>